<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Company');$cid=company_id($pdo);$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=val('action');$id=(int)($_POST['internship_id']??0);
if(in_array($act,['close','reopen'],true)){$s=$pdo->prepare('UPDATE internship SET status=? WHERE internship_id=? AND company_id=?');$s->execute([$act==='close'?'Closed':'Open',$id,$cid]);}
elseif($act==='save'){$title=val('title',180);$status=val('status',20);if(!$title||!in_array($status,['Open','Closed'],true))$err='Title and status required.';else{if($id){$s=$pdo->prepare('UPDATE internship SET title=?,description=?,location=?,duration=?,stipend=?,start_date=?,deadline=?,status=? WHERE internship_id=? AND company_id=?');$s->execute([$title,val('description'),val('location',180),val('duration',80),val('stipend',100),val('start_date',10)?:null,val('deadline',10)?:null,$status,$id,$cid]);}else{$s=$pdo->prepare('INSERT INTO internship(company_id,title,description,location,duration,stipend,start_date,deadline,status) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$cid,$title,val('description'),val('location',180),val('duration',80),val('stipend',100),val('start_date',10)?:null,val('deadline',10)?:null,$status]);}header('Location: internships.php?saved=1');exit;}}}
$edit=null;if(!empty($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM internship WHERE internship_id=? AND company_id=?');$s->execute([(int)$_GET['edit'],$cid]);$edit=$s->fetch();}
$s=$pdo->prepare('SELECT * FROM internship WHERE company_id=? ORDER BY internship_id DESC');$s->execute([$cid]);$rows=$s->fetchAll();$b='<h2>My internships</h2>'.($err?'<p class="error">'.e($err).'</p>':'').(!empty($_GET['saved'])?'<p class="ok">Saved.</p>':'').'<table><tr><th>Title</th><th>Status</th><th>Deadline</th><th>Action</th></tr>';
foreach($rows as $r)$b.='<tr><td>'.e($r['title']).'</td><td>'.e($r['status']).'</td><td>'.e($r['deadline']).'</td><td><a href="?edit='.(int)$r['internship_id'].'">Edit</a> <a href="internship_skills.php?id='.(int)$r['internship_id'].'">Skills</a><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.($r['status']==='Open'?'close':'reopen').'"><input type="hidden" name="internship_id" value="'.(int)$r['internship_id'].'"><button>'.($r['status']==='Open'?'Close':'Reopen').'</button></form></td></tr>';
$b.='</table><h3>'.($edit?'Edit':'Post').' internship</h3><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="save"><input type="hidden" name="internship_id" value="'.(int)($edit['internship_id']??0).'">';
foreach(['title'=>'Title','description'=>'Description','location'=>'Location','duration'=>'Duration','stipend'=>'Stipend','start_date'=>'Start date','deadline'=>'Deadline'] as $k=>$label)$b.='<label>'.e($label).'<input '.(in_array($k,['start_date','deadline'])?'type="date"':'').' name="'.e($k).'" value="'.e($edit[$k]??'').'"></label>';
$b.='<label>Status<select name="status"><option>Open</option><option '.(($edit['status']??'')==='Closed'?'selected':'').'>Closed</option></select></label><button>Save internship</button></form>';page('Manage internships',$b);
